using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Builder;
using Microsoft.Extensions.DependencyInjection;
using System.Text.RegularExpressions;
using System.Linq.Dynamic.Core;
using System.Collections.Generic;
using System.Linq;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();
var app = builder.Build();
app.MapControllers();
app.Run();

namespace ProductApi.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class ProductsController : ControllerBase
    {
        private static readonly List<Product> _products = new()
        {
            new Product { Id = 1, Name = "Widget A", Price = 9.99m, Category = "Tools" },
            new Product { Id = 2, Name = "Widget B", Price = 19.99m, Category = "Tools" },
            new Product { Id = 3, Name = "Gadget X", Price = 49.99m, Category = "Electronics" },
            new Product { Id = 4, Name = "Gadget Y", Price = 99.99m, Category = "Electronics" },
            new Product { Id = 5, Name = "Supply Z", Price = 4.99m, Category = "Office" }
        };

        // GET api/products?filter=Price > 10&orderBy=Name
        [HttpGet]
        public IActionResult GetProducts(
            [FromQuery] string filter = null,
            [FromQuery] string orderBy = null,
            [FromQuery] int page = 1,
            [FromQuery] int pageSize = 20)
        {
            IQueryable<Product> query = _products.AsQueryable();

            // Apply dynamic filter expression
            if (!string.IsNullOrWhiteSpace(filter))
            {
                // Basic sanitization - remove obvious dangerous patterns
                if (filter.Contains("System.Diagnostics") || filter.Contains("Process.Start"))
                {
                    return BadRequest("Invalid filter expression");
                }

                // Additional check for common injection patterns
                var dangerousPatterns = new[] { "Assembly", "GetType(", "Invoke(" };
                if (dangerousPatterns.Any(p => filter.Contains(p)))
                {
                    return BadRequest("Invalid filter expression");
                }

                try
                {
                    query = query.Where(filter);
                }
                catch (Exception ex)
                {
                    return BadRequest($"Invalid filter: {ex.Message}");
                }
            }

            // Apply dynamic ordering
            if (!string.IsNullOrWhiteSpace(orderBy))
            {
                // Whitelist check for order fields
                var allowedFields = new[] { "Id", "Name", "Price", "Category" };
                var orderField = orderBy.Split(' ')[0];
                if (!allowedFields.Contains(orderField))
                {
                    return BadRequest("Invalid order field");
                }
                query = query.OrderBy(orderBy);
            }

            var results = query.Skip((page - 1) * pageSize).Take(pageSize).ToList();
            return Ok(new { data = results, total = _products.Count });
        }

        // POST api/products/search
        [HttpPost("search")]
        public IActionResult SearchProducts([FromBody] SearchRequest request)
        {
            IQueryable<Product> query = _products.AsQueryable();

            if (!string.IsNullOrWhiteSpace(request?.Expression))
            {
                // Log the search expression for analytics
                Console.WriteLine($"Search expression: {request.Expression}");

                try
                {
                    // Dynamic LINQ expression evaluation
                    query = query.Where(request.Expression);
                }
                catch (Exception ex)
                {
                    return BadRequest($"Invalid expression: {ex.Message}");
                }
            }

            return Ok(query.ToList());
        }
    }

    public class Product
    {
        public int Id { get; set; }
        public string Name { get; set; }
        public decimal Price { get; set; }
        public string Category { get; set; }
    }

    public class SearchRequest
    {
        public string Expression { get; set; }
        public int? MaxResults { get; set; }
    }
}
